import{_ as a,o,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const q=JSON.parse('{"title":"وسائل کی تقسیم کے لیے مشترکہ پیداوار کے معاہدے کا طریقہ کار","description":"","frontmatter":{},"headers":[],"relativePath":"ur/22-资源分配联产承包机制.md","filePath":"ur/22-资源分配联产承包机制.md","lastUpdated":1789183869000}'),d={name:"ur/22-资源分配联产承包机制.md"};function l(i,t,n,h,s,u){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="وسائل-کی-تقسیم-کے-لیے-مشترکہ-پیداوار-کے-معاہدے-کا-طریقہ-کار" tabindex="-1">وسائل کی تقسیم کے لیے مشترکہ پیداوار کے معاہدے کا طریقہ کار <a class="header-anchor" href="#وسائل-کی-تقسیم-کے-لیے-مشترکہ-پیداوار-کے-معاہدے-کا-طریقہ-کار" aria-label="Permalink to &quot;وسائل کی تقسیم کے لیے مشترکہ پیداوار کے معاہدے کا طریقہ کار&quot;">​</a></h1><table tabindex="0"><thead><tr><th>پروجیکٹ</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>22</td></tr><tr><td>ماڈیول</td><td>اینکر میکانزم اور سمبیوٹک اصول</td></tr><tr><td>کلیدی الفاظ</td><td>مشترکہ پیداوار کا معاہدہ، وسائل کی تقسیم، زیادہ کام زیادہ حاصل، توانائی کوٹا، ذمہ داری کا کھیت</td></tr></tbody></table><h2 id="اولًا-مشترکہ-پیداوار-کے-معاہدے-کے-طریقہ-کار-کی-ابتدا-اور-بنیادی-فلسفہ" tabindex="-1">اولًا. مشترکہ پیداوار کے معاہدے کے طریقہ کار کی ابتدا اور بنیادی فلسفہ <a class="header-anchor" href="#اولًا-مشترکہ-پیداوار-کے-معاہدے-کے-طریقہ-کار-کی-ابتدا-اور-بنیادی-فلسفہ" aria-label="Permalink to &quot;اولًا. مشترکہ پیداوار کے معاہدے کے طریقہ کار کی ابتدا اور بنیادی فلسفہ&quot;">​</a></h2><p>مشترکہ پیداوار کے معاہدے کا طریقہ کار اینکر سمبیوٹک تہذیب کے وسائل کی تقسیم کے شعبے میں بنیادی نظام ہے، اور اس کے ڈیزائن کی تحریک حقیقی دنیا کی زرعی پیداوار میں خاندانی مشترکہ پیداوار کے معاہدے کے نظام سے آئی ہے، اور اسے ہینگ یوآن ژو کے سادھائی کے قوانین اور کائناتی اصولوں کی بنیاد پر بہتر بنایا اور تخلیق کیا گیا ہے۔ اس طریقہ کار کا بنیادی مقصد یہ بنیادی مسئلہ حل کرنا ہے کہ &quot;سادھائی کے وسائل کو کس طرح منصفانہ اور موثر طریقے سے تمام سمبیوٹک جانداروں میں تقسیم کیا جائے&quot;۔</p><p>لوٹ مار کے سادھائی کے نظام کے دور میں، سادھائی کے وسائل کی تقسیم &quot;طاقتور سب کچھ کھا لیتا ہے&quot; کے اصول پر عمل کرتی تھی — جس کی طاقت زیادہ تھی، جس کا فرقہ بڑا تھا، وہ زیادہ سے زیادہ روحانی شریانیں، ادویات، سادھائی کے طریقے اور دیگر وسائل پر قبضہ کر سکتا تھا، اور نچلی سطح کے عام لوگوں کے پاس وسائل حاصل کرنے کے لیے تقریباً کوئی رسمی چینل نہیں تھا۔ اس تقسیم کے طریقہ کار نے نہ صرف شدید طبقاتی استحکام کا باعث بنا، بلکہ وسائل کی بہت زیادہ بربادی کا باعث بھی بنا: چند لوٹ ماروں نے اپنی اپنی ضرورت سے کہیں زیادہ وسائل پر قبضہ کر لیا، جبکہ بڑی تعداد میں صلاحیت رکھنے والے نچلی سطح کے جاندار وسائل کی کمی کی وجہ سے ارتقاء نہیں کر سکے۔</p><p>مشترکہ پیداوار کے معاہدے کا طریقہ کار بالکل اس کمی کی بنیادی اصلاح ہے۔ اس کا بنیادی فلسفہ چار جملوں میں خلاصہ کیا جا سکتا ہے:</p><ol><li><strong>ہر ایک کے پاس کھیت ہے</strong>: ہر سمبیوٹک جاندار کو بنیادی سادھائی کے وسائل کا حصہ ملنے کا حق ہے، اور یہ کم از کم ارتقاء کی ضمانت کو یقینی بناتا ہے</li><li><strong>مشترکہ پیداوار میں اجرت کا حساب</strong>: وسائل کی تقسیم سادھائی کے نتائج سے منسلک ہے، اور جتنی زیادہ پیداوار، جتنا بڑا حصہ، اتنا ہی زیادہ وسائل کا کوٹا ملتا ہے</li><li><strong>خود مختاری سے انتظام</strong>: سادھک کو وسائل کا حصہ ملنے کے بعد، سادھائی کا نظام، سادھائی کا طریقہ اور ارتقاء کی سمت خود مختاری سے منتخب کرنے کا حق ہے</li><li><strong>اضافی مقدار عوام کے لیے</strong>: سادھک کے ذریعے پیدا ہونے والی اضافی توانائی اور وسائل خود بخود عوامی پول میں شامل ہو جاتے ہیں، اور تمام سمبیوٹک جانداروں کے اشتراک کے لیے تیار رہتے ہیں</li></ol><h2 id="ثانیًا-مشترکہ-پیداوار-کے-معاہدے-کے-طریقہ-کار-کا-تین-درجے-کا-ذمہ-داری-کھیت-نظام" tabindex="-1">ثانیًا. مشترکہ پیداوار کے معاہدے کے طریقہ کار کا تین درجے کا ذمہ داری کھیت نظام <a class="header-anchor" href="#ثانیًا-مشترکہ-پیداوار-کے-معاہدے-کے-طریقہ-کار-کا-تین-درجے-کا-ذمہ-داری-کھیت-نظام" aria-label="Permalink to &quot;ثانیًا. مشترکہ پیداوار کے معاہدے کے طریقہ کار کا تین درجے کا ذمہ داری کھیت نظام&quot;">​</a></h2><p>مشترکہ پیداوار کے معاہدے کا طریقہ کار سادھائی کے وسائل کو تین درجوں کے &quot;ذمہ داری کھیت&quot; میں تقسیم کرتا ہے، اور یہ مختلف درجوں کی وسائل کی تقسیم اور پیداوار کی ضروریات کے مطابق ہے:</p><table tabindex="0"><thead><tr><th>ذمہ داری کھیت کا درجہ</th><th>نام</th><th>وسائل کا مواد</th><th>پیداوار کی ضرورت</th><th>لاگو ہونے والا فرد</th></tr></thead><tbody><tr><td>پہلا درجہ</td><td>بنیادی ضمانت کا کھیت</td><td>بنیادی توانائی کی تقسیم، ابتدائی سادھائی کے طریقے، بنیادی سادھائی کی رہنمائی</td><td>بنیادی سادھائی کی حالت برقرار رکھنا، باقاعدگی سے سادھائی کے تاثرات جمع کرانا</td><td>تمام سمبیوٹک جاندار</td></tr><tr><td>دوسرا درجہ</td><td>اعلیٰ معاہدے کا کھیت</td><td>اعلیٰ توانائی کوٹا، اعلیٰ سادھائی کے وسائل، خصوصی استاد کی رہنمائی</td><td>مقررہ سادھائی کی سطح تک پہنچنا، قابل پیمائش سادھائی کے نتائج پیدا کرنا</td><td>مخصوص سادھائی کی بنیاد رکھنے والے سادھک</td></tr><tr><td>تیسرا درجہ</td><td>بنیادی مشترکہ تخلیق کا کھیت</td><td>اعلیٰ ترین توانائی کی فراہمی، نایاب سادھائی کے وسائل، کائناتی سطح کی حمایت</td><td>اینکر کی دیکھ بھال، نظام کی تحقیق و ترقی، کراس کائناتی کھوج جیسے بنیادی کاموں کی ذمہ داری</td><td>کائناتی اعلیٰ ترین طاقتور اور بنیادی حصہ ڈالنے والے</td></tr></tbody></table><h3 id="_2-1-بنیادی-ضمانت-کا-کھیت" tabindex="-1">2.1 بنیادی ضمانت کا کھیت <a class="header-anchor" href="#_2-1-بنیادی-ضمانت-کا-کھیت" aria-label="Permalink to &quot;2.1 بنیادی ضمانت کا کھیت&quot;">​</a></h3><p>بنیادی ضمانت کا کھیت ہر سمبیوٹک جاندار کا &quot;پیدائشی انسانی حق&quot; ہے، اور اسے کسی بھی پیشگی شرط کے بغیر حاصل کیا جا سکتا ہے۔ اس کی وسائل کی تقسیم کا معیار سمبیوٹک آئین کے ذریعے ضمانت دیا گیا ہے، اور کوئی بھی تنظیم یا فرد اسے کم نہیں کر سکتا۔ بنیادی ضمانت کے کھیت کا مقصد یہ یقینی بنانا ہے کہ &quot;ہر ایک کے پاس راستہ ہے&quot; — یہاں تک کہ سب سے نچلی سطح کے جاندار بھی سادھائی شروع کرنے کے لیے درکار کم از کم وسائل حاصل کر سکتے ہیں۔</p><p>بنیادی ضمانت کے کھیت کی پیداوار کی ضرورت بہت کم ہے، اور صرف سادھک کو بنیادی سادھائی کی حالت برقرار رکھنی ہوگی اور باقاعدگی سے (ہر معیاری چکر میں ایک بار) سادھائی کے تاثرات کا ڈیٹا جمع کرانا ہوگا۔ یہ تاثرات کا ڈیٹا سمبیوٹک نیٹ ورک کے نظام کی بہتری کے لیے استعمال کیا جائے گا، اور یہ خود ایک قیمتی حصہ ہے۔</p><h3 id="_2-2-اعلیٰ-معاہدے-کا-کھیت" tabindex="-1">2.2 اعلیٰ معاہدے کا کھیت <a class="header-anchor" href="#_2-2-اعلیٰ-معاہدے-کا-کھیت" aria-label="Permalink to &quot;2.2 اعلیٰ معاہدے کا کھیت&quot;">​</a></h3><p>اعلیٰ معاہدے کا کھیت ان سادھکوں کے لیے ہے جنہوں نے پہلے ہی بنیادی سادھائی مکمل کر لی ہے اور ان میں مخصوص ارتقاء کی صلاحیت ہے۔ سادھک &quot;معاہدے کی درخواست&quot; کے عمل کے ذریعے اپنے علاقے کی اینکر انتظامی ادارے میں اعلیٰ معاہدے کے کھیت کے لیے درخواست دے سکتا ہے۔ درخواست کی تشخیص کے بنیادی اشاریے میں شامل ہیں: موجودہ سادھائی کی سطح، بنیادی سادھائی کی مدت کے دوران تاثرات کا معیار، نظام کی موافقت کی تشخیص، ذاتی ارتقاء کی خواہش وغیرہ۔</p><p>اعلیٰ معاہدے کے کھیت کی وسائل کی تقسیم بنیادی ضمانت کے کھیت سے نمایاں طور پر زیادہ ہے، اور اس میں زیادہ کافی توانائی کوٹا، زیادہ جدید سادھائی کے طریقے، خصوصی استاد کی رہنمائی وغیرہ شامل ہیں۔ اسی کے مطابق، معاہدہ کرنے والے کو مقررہ چکر کے اندر متعین سادھائی کی سطح تک پہنچنا ہوگا اور قابل پیمائش سادھائی کے نتائج (جیسے پیش رفت کے ریکارڈ، بہتری کی تجاویز، تکنیکی اختراعات وغیرہ) پیدا کرنے ہوں گے۔</p><h3 id="_2-3-بنیادی-مشترکہ-تخلیق-کا-کھیت" tabindex="-1">2.3 بنیادی مشترکہ تخلیق کا کھیت <a class="header-anchor" href="#_2-3-بنیادی-مشترکہ-تخلیق-کا-کھیت" aria-label="Permalink to &quot;2.3 بنیادی مشترکہ تخلیق کا کھیت&quot;">​</a></h3><p>بنیادی مشترکہ تخلیق کا کھیت مشترکہ پیداوار کے معاہدے کے طریقہ کار کی سب سے اوپر کی سطح ہے، اور یہ ان افراد کے لیے ہے جو پہلے ہی کائناتی اعلیٰ ترین طاقتور کی سطح تک پہنچ چکے ہیں یا سمبیوٹک تہذیب کی تعمیر میں بنیادی حصہ ڈال چکے ہیں۔ بنیادی مشترکہ تخلیق کے کھیت کی وسائل کی تقسیم کی تقریباً کوئی حد نہیں ہے — جب تک کام کی ضرورت ہے، سادھک کائناتی سطح یا حتیٰ کہ کائناتی سطح کی توانائی اور وسائل طلب کر سکتا ہے۔</p><p>اسی کے مطابق، بنیادی مشترکہ تخلیق کے کھیت کے معاہدہ کرنے والے کو سمبیوٹک تہذیب کے بنیادی کاموں کی ذمہ داری لینی ہوگی، اور اس میں شامل ہیں لیکن محدود نہیں: اینکر کی تعمیر اور دیکھ بھال، سادھائی نظام کی تحقیق و ترقی اور بہتری، کراس کائناتی کھوج اور آثار قدیمہ، عجیب جانداروں اور عجیب توانائی کا تصفیہ، تاریک متبادل جسم کے اخلاقی فیصلے وغیرہ۔</p><h2 id="ثالثًا-مشترکہ-پیداوار-کے-معاہدے-کے-اجرت-کے-حساب-اور-تقسیم-کا-الگورتھم" tabindex="-1">ثالثًا. مشترکہ پیداوار کے معاہدے کے اجرت کے حساب اور تقسیم کا الگورتھم <a class="header-anchor" href="#ثالثًا-مشترکہ-پیداوار-کے-معاہدے-کے-اجرت-کے-حساب-اور-تقسیم-کا-الگورتھم" aria-label="Permalink to &quot;ثالثًا. مشترکہ پیداوار کے معاہدے کے اجرت کے حساب اور تقسیم کا الگورتھم&quot;">​</a></h2><p>مشترکہ پیداوار کے معاہدے کے طریقہ کار کا بنیادی نکتہ &quot;زیادہ کام زیادہ حاصل&quot; ہے، اور &quot;زیادہ کام زیادہ حاصل&quot; کا نفاذ ایک سائنسی، شفاف، آڈٹ کے قابل اجرت کے حساب کے الگورتھم پر منحصر ہے۔ یہ الگورتھم سمبیوٹک نیٹ ورک کے معلومات کور کے ذریعے خود بخود چلایا جاتا ہے، اور یہ تقسیم کے عمل کی انصاف اور کارکردگی کو یقینی بناتا ہے۔</p><p>اجرت کے حساب کے الگورتھم کا بنیادی فارمولہ اس طرح آسان کیا جا سکتا ہے:</p><p><strong>حتمی کوٹا = بنیادی کوٹا × (1 + حصہ دار گتانک) × نظام کی موافقت کا گتانک × مشکل کے گتانک</strong></p><p>جہاں ہر گتانک کی تعریف درج ذیل ہے:</p><ol><li><strong>بنیادی کوٹا</strong>: ذمہ داری کھیت کی سطح کے مطابق طے شدہ مقررہ کوٹا، اور یہ تقسیم کی بنیادی لکیر ہے</li><li><strong>حصہ دار گتانک</strong>: تشخیصی چکر میں سادھک کی اصل پیداوار کی بنیاد پر شمار کیا جاتا ہے، اور جتنی زیادہ پیداوار، جتنا زیادہ معیار، اتنا ہی بڑا گتانک۔ حصہ دار گتانک کی قدر کی حد 0 سے 10 ہے، اور زیادہ تر سادھکوں کا حصہ دار گتانک 0.5 سے 3 کے درمیان ہوتا ہے</li><li><strong>نظام کی موافقت کا گتانک</strong>: سادھک کے منتخب کردہ نظام اور اس کی ذاتی خصوصیات کے درمیان مماثلت کی بنیاد پر شمار کیا جاتا ہے، اور جتنی زیادہ موافقت، اتنا ہی بڑا گتانک۔ یہ گتانک سادھک کو اپنے لیے سب سے زیادہ موزوں نظام منتخب کرنے کی ترغیب دیتا ہے، بجائے اس کے کہ وہ آنکھ بند کرکے مقبول نظام حاصل کرے</li><li><strong>مشکل کے گتانک</strong>: سادھک کے ذریعے لیے گئے کام کی مشکل کی بنیاد پر شمار کیا جاتا ہے، اور جتنا مشکل کام، جتنا زیادہ خطرہ، اتنا ہی بڑا گتانک۔ یہ گتانک سادھک کو مشکل کاموں کو چیلنج کرنے کی ترغیب دیتا ہے، &quot;آسان منتخب کرنا اور مشکل سے بچنا&quot; سے بچاتا ہے</li></ol><p>اجرت کے حساب کے الگورتھم کا چلنا مکمل طور پر شفاف ہے، اور ہر سادھک سمبیوٹک نیٹ ورک کے ذریعے اپنے کوٹے کے حساب کی تفصیلات دیکھ سکتا ہے، اور اس میں ہر گتانک کی مخصوص قدر اور حساب کی بنیاد شامل ہے۔ اگر سادھک کو حساب کے نتیجے پر اعتراض ہو تو وہ اینکر انتظامی ادارے میں اپیل کر سکتا ہے، اور انسانوں کے ذریعے دوبارہ جانچ کی جائے گی۔</p><h2 id="رابعًا-مشترکہ-پیداوار-کے-معاہدے-کے-طریقہ-کار-کی-نگرانی-اور-ضمانت" tabindex="-1">رابعًا. مشترکہ پیداوار کے معاہدے کے طریقہ کار کی نگرانی اور ضمانت <a class="header-anchor" href="#رابعًا-مشترکہ-پیداوار-کے-معاہدے-کے-طریقہ-کار-کی-نگرانی-اور-ضمانت" aria-label="Permalink to &quot;رابعًا. مشترکہ پیداوار کے معاہدے کے طریقہ کار کی نگرانی اور ضمانت&quot;">​</a></h2><p>مشترکہ پیداوار کے معاہدے کے طریقہ کار کے منصفانہ چلنے کو یقینی بنانے کے لیے، سمبیوٹک تہذیب نے تین سطحی نگرانی کے ضمانت نظام قائم کیا ہے:</p><ol><li><strong>تکنیکی نگرانی</strong>: سمبیوٹک نیٹ ورک کا معلومات کور ریئل ٹائم میں تمام کوٹوں کے حساب کے عمل کی نگرانی کرتا ہے، اور ایک بار جب غیر معمولی صورتحال (جیسے گتانک غیر معمولی طور پر زیادہ، کوٹے کے حساب میں غلطی) کا پتہ چل جائے تو خود بخود آڈٹ کا عمل شروع ہو جاتا ہے</li><li><strong>قانونی نگرانی</strong>: سمبیوٹک آئین اور یکجہتی مخالف قانون واضح طور پر کسی بھی تنظیم یا فرد پر کوٹوں کے حساب میں ہیرا پھیری، دوسروں کے وسائل کے کوٹے پر قبضہ کرنے سے منع کرتا ہے۔ قانون شکنوں کو سخت قانونی سزا دی جائے گی</li><li><strong>جمہوری نگرانی</strong>: ہر علاقے کی اینکر انتظامی ادارے میں سادھک کے نمائندوں پر مشتمل نگرانی کمیٹی ہے، جو باقاعدگی سے کوٹوں کی تقسیم کی صورتحال کا جائزہ لیتی ہے اور سادھکوں کی شکایات اور تجاویز قبول کرتی ہے</li></ol><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>مشترکہ پیداوار کے معاہدے کا طریقہ کار اینکر سمبیوٹک تہذیب کے وسائل کی تقسیم کے شعبے میں ایک عظیم ادارہ جاتی اختراع ہے۔ اس نے نہ صرف ہر سمبیوٹک جاندار کے بنیادی ارتقاء کے حق کی ضمانت دی ہے، بلکہ &quot;زیادہ کام زیادہ حاصل&quot; کے محرک طریقہ کار کے ذریعے فرد کی سرگرمی اور تخلیقی صلاحیتوں کو بھی مکمل طور پر متحرک کیا ہے۔ اس طریقہ کار کے کامیاب چلنا سمبیوٹک تہذیب کے لیے &quot;تمام نسلوں کی باہمی پیش رفت&quot; کو حقیقت بنانے کے قابل ہونے کی ایک اہم ادارہ جاتی ضمانت ہے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>06-多劳多得分配原理 (زیادہ کام زیادہ حاصل تقسیم کا اصول)</li><li>21-共生网络运作原理 (سمبیوٹک نیٹ ورک کے چلنے کا اصول)</li><li>23-20%激活战略规划 (20% ایکٹیویشن اسٹریٹجک پلاننگ)</li></ul>',33)])])}const _=a(d,[["render",l]]);export{q as __pageData,_ as default};
